"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["95458"],{823949(n){n.exports=JSON.parse('{"id":8674,"title":"\u5851\u80F6\u8DD1\u9053\u7684\u8D77\u6E90","description":"\u5851\u80F6\u8DD1\u9053\uFF0C\u53C8\u79F0 \u5408\u6210\u8DD1\u9053 \u6216 \u5168\u5929\u5019\u8DD1\u9053 \uFF0C\u662F\u4E00\u79CD\u7531\u5408\u6210\u6750\u6599\uFF08\u4E3B\u8981\u662F\u805A\u6C28\u916F\u6216\u6A61\u80F6\uFF09\u5236\u6210\u7684\u8FD0\u52A8\u8DD1\u9053\u8868\u9762\u3002\u5B83\u7684\u8D77\u6E90\u548C\u53D1\u5C55\u4E0E\u4EE5\u4E0B\u51E0\u4E2A\u5173\u952E\u9636\u6BB5\u548C\u80CC\u666F\u5BC6\u5207\u76F8\u5173\uFF1A\\n 1. \u65E9\u671F\u80CC\u666F\uFF0820\u4E16\u7EAA60\u5E74\u4EE3\u524D\uFF09 \\n   \u4F20\u7EDF\u8DD1\u9053\u6750\u6599 \uFF1A\u65E9\u671F\u7684\u7530\u5F84\u8DD1\u9053\u591A\u4E3A\u5929\u7136\u6750\u6599\uFF0C\u5982\u7164\u6E23\u3001\u9ECF\u571F\u3001\u6C99\u571F\u7B49\u3002\u8FD9\u4E9B\u6750\u6599\u6210\u672C\u4F4E\uFF0C\u4F46\u5B58\u5728\u8BF8\u591A\u7F3A\u70B9\uFF1A\\n    \u6613\u53D7\u5929\u6C14\u5F71\u54CD\uFF08\u96E8\u96EA\u540E\u6CE5\u6CDE\u3001\u5E72\u71E5\u65F6\u5C18\u571F\u98DE\u626C\uFF09\uFF1B\\n    \u7EF4\u62A4\u6210\u672C\u9AD8\uFF1B\\n    \u8FD0\u52A8\u5458\u5BB9\u6613\u53D7\u4F24\uFF0C\u4E14\u6210\u7EE9\u53D7\u573A\u5730\u6761\u4EF6\u9650\u5236\u3002\\n   2. \u8BDE\u751F\u5951\u673A\uFF1A1960\u5E74\u4EE3 \\n   1964\u5E74\u4E1C\u4EAC\u5965\u8FD0\u4F1A \uFF1A\u65E5\u672C\u4E3A\u6539\u5584\u6BD4\u8D5B\u6761\u4EF6\uFF0C\u9996\u6B21\u5C1D\u8BD5\u4F7F\u7528 \u805A\u6C28\u916F\u6750\u6599 \u94FA\u8BBE\u90E8\u5206\u8DD1\u9053\u533A\u57DF\uFF0C\u4F46\u5E76\u975E\u5B8C\u6574\u7684\u5851\u80F6\u8DD1\u9053\u3002\\n   \u5173\u952E\u7A81\u7834\u2014\u20141968\u5E74\u58A8\u897F\u54E5\u57CE\u5965\u8FD0\u4F1A \uFF1A\\n    \u4E3A\u5E94\u5BF9\u9AD8\u6D77\u62D4\u3001\u591A\u96E8\u7684\u6C14\u5019\uFF0C\u540C\u65F6\u63D0\u4F9B\u66F4\u516C\u5E73\u7684\u7ADE\u8D5B\u73AF\u5883\uFF0C\u4E3B\u529E\u65B9\u4E0E\u7F8E\u56FD\u516C\u53F8 3M \u5408\u4F5C\uFF0C\u5728\u5965\u6797\u5339\u514B\u4F53\u80B2\u573A\u94FA\u8BBE\u4E86\u5168\u7403\u7B2C\u4E00\u6761 \u805A\u6C28\u916F\u5851\u80F6\u8DD1\u9053 \uFF08\u54C1\u724C\u540D\u4E3A\u201CTartan\u201D\uFF09\u3002\\n    \u8FD9\u6761\u8DD1\u9053\u663E\u8457\u51CF\u5C11\u4E86\u8FD0\u52A8\u5458\u53D7\u4F24\u98CE\u9669\uFF0C\u63D0\u5347\u4E86\u6210\u7EE9\uFF08\u5C24\u5176\u662F\u77ED\u8DD1\u548C\u8DF3\u8DC3\u9879\u76EE\uFF09\uFF0C\u5E76\u5B9E\u73B0\u4E86\u201C\u5168\u5929\u5019\u201D\u4F7F\u7528\uFF0C\u4E0D\u53D7\u96E8\u6C34\u5F71\u54CD\u3002\\n    \u8BE5\u5C4A\u5965\u8FD0\u4F1A\u4E0A\uFF0C\u8FD0\u52A8\u5458\u5728\u5851\u80F6\u8DD1\u9053\u4E0A\u521B\u9020\u4E86\u591A\u9879\u4E16\u754C\u7EAA\u5F55\uFF0C\u8BC1\u660E\u4E86\u5176\u4F18\u8D8A\u6027\uFF0C\u4ECE\u6B64\u5F15\u53D1\u5168\u7403\u5173\u6CE8\u3002\\n   3. \u53D1\u5C55\u4E0E\u666E\u53CA\uFF081970 1990\u5E74\u4EE3\uFF09 \\n   \u6750\u6599\u6539\u8FDB \uFF1A\u805A\u6C28\u916F\u8DD1\u9053\u9010\u6E10\u6F14\u53D8\u4E3A \u4E24\u5C42\u7ED3\u6784 \uFF1A\u5E95\u5C42\u4E3A\u5F39\u6027\u5C42\uFF08\u5438\u6536\u51B2\u51FB\uFF09\uFF0C\u8868\u5C42\u4E3A\u8010\u78E8\u9632\u6ED1\u5C42\u3002\\n   \u73AF\u4FDD\u4E0E\u5B89\u5168\u5347\u7EA7 \uFF1A\\n    \u65E9\u671F\u805A\u6C28\u916F\u8DD1\u9053\u4F7F\u7528 \u7532\u82EF\u4E8C\u5F02\u6C30\u9178\u916F\uFF08TDI\uFF09 \u7B49\u6709\u6BD2\u6EB6\u5242\uFF0C\u53EF\u80FD\u91CA\u653E\u6709\u5BB3\u6C14\u4F53\u300221\u4E16\u7EAA\u540E\uFF0C\u73AF\u4FDD\u578B\u6750\u6599\uFF08\u5982\u6C34\u6027\u6811\u8102\u3001\u9884\u5236\u6A61\u80F6\u5377\u6750\uFF09\u6210\u4E3A\u4E3B\u6D41\u3002\\n    \u56FD\u9645\u7530\u8054\uFF08World Athletics\uFF09\u5236\u5B9A\u4E86\u8DD1\u9053\u8BA4\u8BC1\u6807\u51C6\uFF0C\u786E\u4FDD\u5F39\u6027\u3001\u6469\u64E6\u529B\u548C\u5B89\u5168\u6027\u3002\\n   \u5E7F\u6CDB\u5E94\u7528 \uFF1A\u4ECE\u4E13\u4E1A\u4F53\u80B2\u573A\u9986\u6269\u5C55\u5230\u5B66\u6821\u3001\u793E\u533A\u8FD0\u52A8\u573A\uFF0C\u6210\u4E3A\u5168\u7403\u7530\u5F84\u573A\u5730\u7684\u6807\u51C6\u914D\u7F6E\u3002\\n   4. \u73B0\u4EE3\u5851\u80F6\u8DD1\u9053\u7684\u7C7B\u578B \\n1.  \u6DF7\u5408\u578B \uFF1A\u805A\u6C28\u916F\u6DF7\u5408\u6A61\u80F6\u9897\u7C92\uFF0C\u4E13\u4E1A\u8D5B\u4E8B\u5E38\u7528\u3002\\n2.  \u900F\u6C14\u578B \uFF1A\u5E95\u5C42\u4E3A\u900F\u6C14\u7ED3\u6784\uFF0C\u9002\u5408\u591A\u96E8\u5730\u533A\u3002\\n3.  \u9884\u5236\u578B \uFF1A\u5DE5\u5382\u751F\u4EA7\u7684\u6A61\u80F6\u5377\u6750\uFF0C\u73B0\u573A\u94FA\u8BBE\uFF0C\u73AF\u4FDD\u4E14\u6027\u80FD\u7A33\u5B9A\u3002\\n4.  EPDM\u6A61\u80F6\u578B \uFF1A\u5F69\u8272\u9897\u7C92\u94FA\u8BBE\uFF0C\u5E38\u89C1\u4E8E\u5B66\u6821\u64CD\u573A\u3002\\n   5. \u4E89\u8BAE\u4E0E\u6311\u6218 \\n   \u73AF\u4FDD\u95EE\u9898 \uFF1A\u65E9\u671F\u6750\u6599\u542B\u91CD\u91D1\u5C5E\u3001\u6325\u53D1\u6027\u6709\u673A\u7269\uFF08VOC\uFF09\uFF0C\u5E9F\u5F03\u540E\u96BE\u964D\u89E3\u3002\u76EE\u524D\u63A8\u5E7F \u53EF\u56DE\u6536\u8DD1\u9053 \u548C\u73AF\u4FDD\u6750\u6599\u3002\\n   \u5065\u5EB7\u4E89\u8BAE \uFF1A\u4E2D\u56FD\u66FE\u66DD\u5149\u201C\u6BD2\u8DD1\u9053\u201D\u4E8B\u4EF6\uFF08\u5B66\u6821\u8DD1\u9053\u91CA\u653E\u6709\u6BD2\u6C14\u4F53\uFF09\uFF0C\u63A8\u52A8\u884C\u4E1A\u6807\u51C6\u5347\u7EA7\uFF08\u5982\u4E2D\u56FD\u56FD\u5BB6\u6807\u51C6GB 36246 2018\uFF09\u3002\\n   \u6210\u672C\u4E0E\u7EF4\u62A4 \uFF1A\u5851\u80F6\u8DD1\u9053\u9020\u4EF7\u9AD8\u4E8E\u4F20\u7EDF\u6750\u6599\uFF0C\u9700\u5B9A\u671F\u6E05\u6D01\u548C\u4FEE\u8865\u3002\\n6. \u610F\u4E49\u4E0E\u5F71\u54CD \\n   \u4F53\u80B2\u79D1\u5B66\u8FDB\u6B65 \uFF1A\u63D0\u4F9B\u4E00\u81F4\u6027\u548C\u53EF\u9884\u6D4B\u6027\u7684\u6BD4\u8D5B\u6761\u4EF6\uFF0C\u52A9\u529B\u8FD0\u52A8\u5458\u7A81\u7834\u6781\u9650\u3002\\n   \u5927\u4F17\u4F53\u80B2\u666E\u53CA \uFF1A\u5168\u5929\u5019\u7279\u6027\u4F7F\u8FD0\u52A8\u573A\u5730\u4F7F\u7528\u7387\u5927\u5E45\u63D0\u5347\u3002\\n   \u7ECF\u6D4E\u6548\u76CA \uFF1A\u5E26\u52A8\u4E86\u8FD0\u52A8\u6750\u6599\u4EA7\u4E1A\u7684\u53D1\u5C55\uFF0C\u5F62\u6210\u5168\u7403\u4EA7\u4E1A\u94FE\u3002\\n   \u603B\u7ED3 \\n\u5851\u80F6\u8DD1\u9053\u7684\u8D77\u6E90\u662F \u4F53\u80B2\u79D1\u6280\u4E0E\u5DE5\u7A0B\u7ED3\u5408\u7684\u91CC\u7A0B\u7891 \uFF0C\u4ECE1968\u5E74\u58A8\u897F\u54E5\u57CE\u5965\u8FD0\u4F1A\u7684\u9996\u6B21\u5927\u89C4\u6A21\u5E94\u7528\uFF0C\u5230\u5982\u4ECA\u6210\u4E3A\u5168\u7403\u8FD0\u52A8\u573A\u5730\u7684\u6807\u51C6\u914D\u7F6E\uFF0C\u5B83\u53CD\u6620\u4E86\u4EBA\u7C7B\u5BF9\u66F4\u5B89\u5168\u3001\u516C\u5E73\u3001\u9AD8\u6548\u8FD0\u52A8\u73AF\u5883\u7684\u4E0D\u61C8\u8FFD\u6C42\u3002\u672A\u6765\uFF0C\u968F\u7740\u73AF\u4FDD\u6280\u672F\u548C\u6750\u6599\u79D1\u5B66\u7684\u8FDB\u6B65\uFF0C\u5851\u80F6\u8DD1\u9053\u5C06\u7EE7\u7EED\u5411\u66F4\u53EF\u6301\u7EED\u7684\u65B9\u5411\u6F14\u8FDB\u3002","owner":"YZSPORT","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:38:51.486Z"}')}}]);